#include "io.h"
#include <QFile>
#include <QCoreApplication>
#include <QFileInfo>
#include <QJsonArray>
#include <opencv2/imgcodecs.hpp>
#include <opencv2/imgproc.hpp>
cv::Mat readImage(const QString& path){QFile file(path);if(!file.open(QIODevice::ReadOnly))return {};QByteArray bytes=file.readAll();std::vector<uchar> data(bytes.begin(),bytes.end());return cv::imdecode(data,cv::IMREAD_COLOR);}
bool writeImage(const QString& path,const cv::Mat& image){std::vector<uchar> bytes;QString suffix=QFileInfo(path).suffix().toLower();if(suffix.isEmpty())return false;try{if(!cv::imencode(("."+suffix).toStdString(),image,bytes))return false;}catch(...){return false;}QFile file(path);return file.open(QIODevice::WriteOnly)&&file.write(reinterpret_cast<const char*>(bytes.data()),qint64(bytes.size()))==qint64(bytes.size());}
cv::Mat annotate(const cv::Mat& image,const DetectionResult& result){cv::Mat out=image.clone();const cv::Scalar colors[]={{40,180,40},{0,220,220},{0,140,255}};for(const auto& d:result.detections){cv::rectangle(out,d.box,colors[d.classId],2);cv::putText(out,(d.className+QString(" %1").arg(d.confidence,0,'f',2)).toStdString(),{int(d.box.x),std::max(18,int(d.box.y)-4)},cv::FONT_HERSHEY_SIMPLEX,0.55,colors[d.classId],2);}return out;}
QJsonObject resultJson(const DetectionResult& r){QJsonArray detections;for(const auto& d:r.detections)detections.append(QJsonObject{{"class_id",d.classId},{"class_name",d.className},{"confidence",d.confidence},{"xyxy",QJsonArray{d.box.x,d.box.y,d.box.x+d.box.width,d.box.y+d.box.height}}});return {{"ok",r.ok},{"error",r.error},{"protocol",r.protocol},{"detections",detections},{"timing_ms",QJsonObject{{"preprocess",r.preprocessMs},{"inference",r.inferenceMs},{"postprocess",r.postprocessMs},{"total",r.totalMs}}}};}
void addDetectorArguments(QCommandLineParser& p){p.addHelpOption();p.addOption({"backend","Inference backend","backend","mnn"});p.addOption({"model","Absolute model path","path",QCoreApplication::applicationDirPath()+"/models/trained_fp32.mnn"});p.addOption({"threads","CPU thread count","count","4"});p.addOption({"confidence","Confidence threshold","value","0.25"});p.addOption({"nms","Class-aware NMS IoU threshold","value","0.45"});}
bool parseDetectorArguments(const QCommandLineParser& p,DetectorOptions& o,QString& error){bool threads=false,conf=false,nms=false;o.backend=p.value("backend");o.modelPath=p.value("model");o.threads=p.value("threads").toInt(&threads);o.confidence=p.value("confidence").toFloat(&conf);o.nms=p.value("nms").toFloat(&nms);if(!threads||!conf||!nms||o.threads<1||o.threads>64||!(o.confidence>=0&&o.confidence<=1)||!(o.nms>=0&&o.nms<=1)||!QFileInfo(o.modelPath).isAbsolute()||(o.backend!="opencv"&&o.backend!="mnn")){error="ARGUMENT_INVALID: require absolute --model, valid backend, threads 1..64 and thresholds 0..1";return false;}return true;}
